export const MapTooltip: React.FC = () => {
  const { showTooltip, tooltipData, tooltipPosition } = useTooltipState();

  if (!showTooltip || !tooltipData) {
    return null;
  }

  const tooltipType = getTooltipType(tooltipData);

  // Position tooltip to avoid going off screen
  const adjustedPosition = {
    left: Math.min(tooltipPosition.x + 10, window.innerWidth - 280),
    top: Math.min(tooltipPosition.y + 10, window.innerHeight - 300),
  };

  // If tooltip would go off the right edge, position it to the left of cursor
  if (tooltipPosition.x + 280 > window.innerWidth) {
    adjustedPosition.left = tooltipPosition.x - 280 - 10;
  }

  // If tooltip would go off the bottom edge, position it above cursor
  if (tooltipPosition.y + 300 > window.innerHeight) {
    adjustedPosition.top = tooltipPosition.y - 300 - 10;
  }

  return (
    <div
      className="absolute z-50 pointer-events-none"
      style={{
        left: adjustedPosition.left,
        top: adjustedPosition.top,
      }}
    >
      <div className="bg-white rounded-lg shadow-lg border border-gray-200 p-4 max-w-sm">
        {tooltipType === 'h3' && <H3Tooltip data={tooltipData} />}
        {tooltipType === 'kommune' && <KommuneTooltip data={tooltipData} />}
        {tooltipType === 'bnbo' && <BNBOTooltip data={tooltipData} />}
        {tooltipType === 'unknown' && (
          <div className="space-y-3">
            <div className="bg-gradient-to-r from-amber-500 to-orange-600 px-4 py-3 rounded-lg text-white">
              <div className="flex items-center space-x-2">
                <div className="w-5 h-5 bg-white/20 rounded-full flex items-center justify-center">
                  <span className="text-xs">?</span>
                </div>
                <div>
                  <h3 className="font-bold">Data Point</h3>
                  <p className="text-amber-100 text-sm">Hover data available</p>
                </div>
              </div>
            </div>

            <div className="space-y-2">
              {Object.entries(tooltipData).map(([key, value]) => {
                if (value === null || value === undefined) return null;
                
                const formattedKey = key
                  .replace(/_/g, ' ')
                  .replace(/\b\w/g, l => l.toUpperCase());
                
                return (
                  <div key={key} className="flex justify-between items-center py-1 border-b border-gray-100 last:border-b-0">
                    <span className="text-gray-600 text-sm font-medium">{formattedKey}:</span>
                    <span className="text-gray-900 font-semibold text-sm">
                      {typeof value === 'number' ? formatNumber(value) : String(value)}
                    </span>
                  </div>
                );
              })}
            </div>

            <details className="mt-3">
              <summary className="text-xs text-gray-500 cursor-pointer hover:text-gray-700">
                View raw data
              </summary>
              <pre className="text-xs mt-2 p-2 bg-gray-100 rounded overflow-auto max-h-32 text-gray-700">
                {JSON.stringify(tooltipData, null, 2)}
              </pre>
            </details>
          </div>
        )}
      </div>
    </div>
  );
};

export default MapTooltip; 